<?php require __DIR__ . '/communication_operations_ui.php';
$campaignCounts=array('draft'=>0,'scheduled'=>0,'sending'=>0,'sent'=>0,'failed'=>0,'archived'=>0,'cancelled'=>0);
foreach($rows as $campaignCountRow){$key=(string)$campaignCountRow['status'];if(isset($campaignCounts[$key]))$campaignCounts[$key]++;}
$readyCount=$campaignCounts['draft']+$campaignCounts['scheduled'];
$campaignCounts['sent'] += $campaignCounts['archived'] + $campaignCounts['cancelled'];
$favoriteRows=array();$activeRows=array();$archivedRows=array();
foreach($rows as $campaignRow){
 if(!empty($campaignRow['is_favorite']))$favoriteRows[]=$campaignRow;
 elseif((string)$campaignRow['status']==='archived')$archivedRows[]=$campaignRow;
 else $activeRows[]=$campaignRow;
}
$campaignGroups=array(
 array('title'=>'Favoritas','description'=>'Campañas reutilizables que querés tener siempre a mano.','rows'=>$favoriteRows,'class'=>'is-favorites'),
 array('title'=>'Campañas actuales','description'=>'Borradores, programadas y envíos recientes que todavía forman parte del trabajo actual.','rows'=>$activeRows,'class'=>'is-active'),
 array('title'=>'Campañas archivadas','description'=>'Campañas cerradas que conservás como referencia.','rows'=>$archivedRows,'class'=>'is-archived'),
);
?>
