ue="preview_saved">Vista previa</button></form><form method="post"><input type="hidden" name="csrf" value="<?php echo e($csrf);?>"><input type="hidden" name="id" value="<?php echo (int)$r['id'];?>"><button class="btn secondary" name="action" value="duplicate">Duplicar</button></form><form method="post"><input type="hidden" name="csrf" value="<?php echo e($csrf);?>"><input type="hidden" name="id" value="<?php echo (int)$r['id'];?>"><button class="btn secondary<?php echo !empty($r['is_favorite'])?' campaign-star':'';?>" name="action" value="toggle_favorite"><?php echo !empty($r['is_favorite'])?'Quitar favorita':'Favorita';?></button></form><form method="post"><input type="hidden" name="csrf" value="<?php echo e($csrf);?>"><input type="hidden" name="id" value="<?php echo (int)$r['id'];?>"><button class="btn secondary" name="action" value="<?php echo (string)$r['status']==='archived'?'activate':'archive';?>"><?php echo (string)$r['status']==='archived'?'Reactivar':'Archivar';?></button></form><?php if((string)$r['status']!=='sending'):?><form method="post" onsubmit="return confirm('¿Eliminar esta campaña de la vista? Sus envíos y métricas históricas se conservarán.');"><input type="hidden" name="csrf" value="<?php echo e($csrf);?>"><input type="hidden" name="id" value="<?php echo (int)$r['id'];?>"><button class="btn secondary campaign-delete" name="action" value="remove_campaign">Eliminar</button></form><?php endif;?></div></article>
